import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[][] a = new long[4][n];
        for (long[] row : a) for (int i = 0; i < n; i++) row[i] = nextLong();
        long[] points = new long[n], diff = new long[n];
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            points[i] = 3 * a[0][i] + a[1][i];
            diff[i] = a[2][i] - a[3][i];
            order[i] = i;
        }
        // rank by points, then goal difference, both descending; index only fixes ties
        Arrays.sort(order, (x, y) -> points[x] != points[y] ? Long.compare(points[y], points[x])
                : diff[x] != diff[y] ? Long.compare(diff[y], diff[x]) : Integer.compare(x, y));
        System.out.println(order[0] + " " + order[1]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	var a [4][]int
	for r := range a {
		a[r] = make([]int, n)
		for i := range a[r] {
			a[r][i] = readInt()
		}
	}
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	// rank by points, then goal difference, both descending; index only fixes ties
	sort.Slice(order, func(x, y int) bool {
		i, j := order[x], order[y]
		pi, pj := 3*a[0][i]+a[1][i], 3*a[0][j]+a[1][j]
		if pi != pj {
			return pi > pj
		}
		di, dj := a[2][i]-a[3][i], a[2][j]-a[3][j]
		if di != dj {
			return di > dj
		}
		return i < j
	})
	fmt.Println(order[0], order[1])
}
